package com.freshproduce.pos.domain;

import jakarta.persistence.*;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.LocalDateTime;

/** A forecast generated by the AI forecasting service (FR-05). */
@Entity
@Table(name = "sales_forecast")
public class SalesForecast {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    @Column(name = "forecast_id")
    private Long id;

    @ManyToOne(optional = false, fetch = FetchType.EAGER)
    @JoinColumn(name = "product_id")
    private Product product;

    @Column(name = "period_start", nullable = false)
    private LocalDate periodStart;

    @Column(name = "period_end", nullable = false)
    private LocalDate periodEnd;

    @Column(name = "forecast_period", nullable = false)
    private int forecastPeriodDays;

    @Column(name = "predicted_quantity", nullable = false, precision = 12, scale = 2)
    private BigDecimal predictedQuantity;

    @Column(name = "model_type", length = 50)
    private String modelType;

    @Column(name = "model_mae", precision = 12, scale = 2)
    private BigDecimal modelMae;

    @Column(name = "baseline_mae", precision = 12, scale = 2)
    private BigDecimal baselineMae;

    /** Accuracy score reported by the model (100% minus mean absolute percentage error on the hold-out period). */
    @Column(name = "accuracy_percent", precision = 5, scale = 2)
    private BigDecimal accuracyPercent;

    /** JSON array of {date, quantity} daily predictions as returned by the AI service. */
    @Column(name = "daily_predictions", length = 8000)
    private String dailyPredictionsJson;

    @ManyToOne(fetch = FetchType.EAGER)
    @JoinColumn(name = "requested_by")
    private User requestedBy;

    @Column(name = "created_date", nullable = false)
    private LocalDateTime createdDate = LocalDateTime.now();

    public Long getId() { return id; }
    public void setId(Long id) { this.id = id; }
    public Product getProduct() { return product; }
    public void setProduct(Product product) { this.product = product; }
    public LocalDate getPeriodStart() { return periodStart; }
    public void setPeriodStart(LocalDate periodStart) { this.periodStart = periodStart; }
    public LocalDate getPeriodEnd() { return periodEnd; }
    public void setPeriodEnd(LocalDate periodEnd) { this.periodEnd = periodEnd; }
    public int getForecastPeriodDays() { return forecastPeriodDays; }
    public void setForecastPeriodDays(int forecastPeriodDays) { this.forecastPeriodDays = forecastPeriodDays; }
    public BigDecimal getPredictedQuantity() { return predictedQuantity; }
    public void setPredictedQuantity(BigDecimal predictedQuantity) { this.predictedQuantity = predictedQuantity; }
    public String getModelType() { return modelType; }
    public void setModelType(String modelType) { this.modelType = modelType; }
    public BigDecimal getModelMae() { return modelMae; }
    public void setModelMae(BigDecimal modelMae) { this.modelMae = modelMae; }
    public BigDecimal getBaselineMae() { return baselineMae; }
    public void setBaselineMae(BigDecimal baselineMae) { this.baselineMae = baselineMae; }
    public BigDecimal getAccuracyPercent() { return accuracyPercent; }
    public void setAccuracyPercent(BigDecimal accuracyPercent) { this.accuracyPercent = accuracyPercent; }
    public String getDailyPredictionsJson() { return dailyPredictionsJson; }
    public void setDailyPredictionsJson(String dailyPredictionsJson) { this.dailyPredictionsJson = dailyPredictionsJson; }
    public User getRequestedBy() { return requestedBy; }
    public void setRequestedBy(User requestedBy) { this.requestedBy = requestedBy; }
    public LocalDateTime getCreatedDate() { return createdDate; }
    public void setCreatedDate(LocalDateTime createdDate) { this.createdDate = createdDate; }
}
